// Santha consumer — Android app module with dev / stg / prod flavors.
// Other platform files are generated by `melos run platforms` (flutter create keeps this file).
plugins {
    id("com.android.application")
    // The Flutter Gradle Plugin must be applied after the Android and Kotlin Gradle plugins.
    id("dev.flutter.flutter-gradle-plugin")
}

// Release signing: CI (apps-release.yml) sets these from secrets. Without them, release builds fall back to the
// debug key so local `flutter build --release` still works (such builds cannot be uploaded to Play).
val releaseKeystore: String? = System.getenv("SANTHA_KEYSTORE_PATH")

android {
    namespace = "app.santha.consumer"
    compileSdk = flutter.compileSdkVersion
    ndkVersion = flutter.ndkVersion

    compileOptions {
        sourceCompatibility = JavaVersion.VERSION_17
        targetCompatibility = JavaVersion.VERSION_17
    }

    defaultConfig {
        applicationId = "app.santha.consumer"
        minSdk = 24 // Android 7.0 — covers the low-end devices common in Nellore
        targetSdk = flutter.targetSdkVersion
        versionCode = flutter.versionCode
        versionName = flutter.versionName
    }

    // AGP 9 disables resValue by default; flavors use it for the launcher label.
    buildFeatures {
        resValues = true
    }

    flavorDimensions += "env"
    productFlavors {
        create("dev") {
            dimension = "env"
            applicationIdSuffix = ".dev"
            versionNameSuffix = "-dev"
            resValue("string", "app_name", "Santha Dev")
        }
        create("stg") {
            dimension = "env"
            applicationIdSuffix = ".stg"
            versionNameSuffix = "-stg"
            resValue("string", "app_name", "Santha Test")
        }
        create("prod") {
            dimension = "env"
            resValue("string", "app_name", "Santha")
        }
    }

    signingConfigs {
        if (releaseKeystore != null) {
            create("release") {
                storeFile = file(releaseKeystore)
                storePassword = System.getenv("SANTHA_KEYSTORE_PASSWORD")
                keyAlias = System.getenv("SANTHA_KEY_ALIAS")
                keyPassword = System.getenv("SANTHA_KEY_PASSWORD")
            }
        }
    }

    buildTypes {
        release {
            signingConfig = signingConfigs.getByName(if (releaseKeystore != null) "release" else "debug")
            isMinifyEnabled = true
            isShrinkResources = true
        }
    }
}

kotlin {
    compilerOptions {
        jvmTarget = org.jetbrains.kotlin.gradle.dsl.JvmTarget.JVM_17
    }
}

flutter {
    source = "../.."
}
